:root {
  --color-bg: #f7f7f5;
  --color-surface: #ffffff;
  --color-text: #1c1c1e;
  --color-muted: #6a6a6f;
  --color-line: #e3e3e0;
  --color-brand: #2f43d6;
  --color-brand-text: #ffffff;
  --color-danger-bg: #fdecec;
  --color-danger: #a61b1b;
  --color-warning-bg: #fff4dd;
  --color-warning: #7a4b00;
  --color-info-bg: #e9f0ff;
  --color-info: #1d3f9a;
  --color-ok: #16794a;
  --space-1: 4px;
  --space-2: 8px;
